    stack.push(id);
    for (const dependency of [...byId.get(id)!.dependsOn].sort()) {
      if (state.get(dependency) === 1) {
        return [...stack.slice(stack.indexOf(dependency)), dependency];
      }
      if (state.get(dependency) !== 2) {
        const cycle = visit(dependency);
        if (cycle) return cycle;
      }
    }
    stack.pop();
    state.set(id, 2);
    return undefined;
  };

  for (const id of [...byId.keys()].sort()) {
    if (!state.has(id)) {
      const cycle = visit(id);
      if (cycle) return cycle;
    }
  }
  return undefined;
}

function plan(tasks: Task[]): Plan {
  const byId = new Map(tasks.map((task) => [task.id, task]));
  const dependents = new Map<string, string[]>(tasks.map((task) => [task.id, []]));
  const remaining = new Map<string, number>();
  for (const task of tasks) {
    remaining.set(task.id, task.dependsOn.length);
    for (const dependency of task.dependsOn) dependents.get(dependency)!.push(task.id);
  }
  for (const children of dependents.values()) children.sort();

  const ready = tasks.filter((task) => task.dependsOn.length === 0).map((task) => task.id).sort();
  const order: string[] = [];
  while (ready.length > 0) {
    const id = ready.shift()!;
    order.push(id);
    for (const child of dependents.get(id)!) {
      const count = remaining.get(child)! - 1;
      remaining.set(child, count);
      if (count === 0) {
        ready.push(child);
        ready.sort();
      }
    }
  }
  if (order.length !== tasks.length) {
    const cycle = findCycle(tasks) ?? [];
    fail(`Dependency cycle detected: ${cycle.join(" -> ")}`);
  }

  const earliest: Plan["earliest"] = {};
  const paths = new Map<string, string[]>();
  const layerById = new Map<string, number>();
  const layers: string[][] = [];
  let totalDuration = 0;
  let criticalPath: string[] = [];

  for (const id of order) {
    const task = byId.get(id)!;
    let start = 0;
    let chosenPath: string[] = [];
    let layer = 0;
    for (const dependency of task.dependsOn) {
      const dependencyTiming = earliest[dependency];
      if (dependencyTiming.finish > start) {
        start = dependencyTiming.finish;
        chosenPath = paths.get(dependency)!;
      } else if (dependencyTiming.finish === start) {
        const alternative = paths.get(dependency)!;
        if (chosenPath.length === 0 || comparePaths(alternative, chosenPath) < 0) chosenPath = alternative;
      }
      layer = Math.max(layer, layerById.get(dependency)! + 1);
    }
    const finish = start + task.duration;
    earliest[id] = { start, finish };
    const taskPath = [...chosenPath, id];
    paths.set(id, taskPath);
    layerById.set(id, layer);
    (layers[layer] ??= []).push(id);

    if (finish > totalDuration || (finish === totalDuration && comparePaths(taskPath, criticalPath) < 0)) {
      totalDuration = finish;
      criticalPath = taskPath;
    }
  }
  for (const layer of layers) layer.sort();
  return { order, layers, earliest, totalDuration, criticalPath };
}

function comparePaths(left: string[], right: string[]): number {
  for (let index = 0; index < Math.min(left.length, right.length); index += 1) {
    if (left[index] < right[index]) return -1;
    if (left[index] > right[index]) return 1;
  }
  return left.length - right.length;
}

async function main(): Promise<void> {
  const args = process.argv.slice(2);
  if (args.length !== 2 || args[0] !== "plan" || args[1].startsWith("-")) {
    fail("Usage: bun run src/cli.ts plan INPUT.json");
  }

  let parsed: unknown;
  try {
    parsed = JSON.parse(await Bun.file(args[1]).text());
  } catch (error) {
    const detail = error instanceof Error ? error.message : String(error);
    fail(`Unable to read valid JSON from '${args[1]}': ${detail}`);
  }
  console.log(JSON.stringify(plan(validateInput(parsed))));
}

main().catch((error: unknown) => {
  console.error(error instanceof Error ? error.message : String(error));
  process.exit(1);
});

